def load(k):
    return open(os.path.join(BASE, F[k][1]), encoding='utf-8').read()
def ws(s): return re.sub(r'\s+', ' ', s)
cache = {k: load(k) for k in F}
fails, exact, wsn = [], 0, 0
def check(inst, q):
    global exact, wsn
    t = cache[inst]
    if q in t: exact += 1; return 'EXACT'
    if ws(q) in ws(t): wsn += 1; return 'WS'
    fails.append((inst, q)); return 'FAIL'
def sha(k): return hashlib.sha256(open(os.path.join(BASE,F[k][1]),'rb').read()).hexdigest()[:16]
with open(os.path.join(BASE,'observations.tsv'),'w',newline='',encoding='utf-8') as f:
    w = csv.writer(f, delimiter='\t', lineterminator='\n')
    w.writerow(['concept','phrase_verbatim','language','instrument','locator','context_quote_verbatim','quote_check','text_file','text_sha256_prefix'])
    for c,p,i,l,q in OBS:
        w.writerow([c,p,'DE',F[i][0],l,q,check(i,q),F[i][1],sha(i)])
with open(os.path.join(BASE,'reverse-harvest.tsv'),'w',newline='',encoding='utf-8') as f:
    w = csv.writer(f, delimiter='\t', lineterminator='\n')
    w.writerow(['phrase_as_instrument_writes_it','language','instrument','locator','context_quote_verbatim','quote_check','text_file','note_and_gloss_OURS_not_an_equivalence'])
    for p,i,l,q,n in RH:
        w.writerow([p,'DE',F[i][0],l,q,check(i,q),F[i][1],n])
# phrase-in-quote check: the phrase (or each part split on ' / ' or '...') should occur in its instrument text
pmiss = []
for c,p,i,l,q in OBS:
    if ws(p) not in ws(cache[i]): pmiss.append((i,p))
print('quotes EXACT', exact, 'WS', wsn, 'FAIL', len(fails))
for x in fails: print('FAIL', x)
print('observation phrases not found verbatim in their instrument:', pmiss)
sys.exit(1 if fails else 0)
